set -euo pipefail

repo_root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
work_root="${RDF4J_CANONICAL_COMPAT_WORKDIR:-${repo_root}/target/canonical-iri-compatibility}"
regenerate=false
with_prechange_baseline=false
regenerate_unsupported=false
usage() {
    cat <<EOF
Usage: $0 [--regenerate-fixtures] [--with-prechange-baseline] [--regenerate-unsupported-format6]

Build the actual RDF4J 6.1.0 release and verify format-2 read/write/reopen compatibility,
format-7 rejection by that release, and current rejection of unsupported format 6.

  --regenerate-fixtures            Regenerate the positive format-2 compatibility fixture.
  --with-prechange-baseline        Also build the old format-6 binary for benchmarks and
                                  its rejection of interrupted format-7 bulk publication.
  --regenerate-unsupported-format6 Regenerate the negative-only format-6 fixture; implies
                                  --with-prechange-baseline. No current format-6 support.

Set RDF4J_CANONICAL_COMPAT_WORKDIR to reuse a different build/evidence directory.
EOF
}
while [[ $# -gt 0 ]]; do
    case $1 in
        --regenerate-fixtures) regenerate=true ;;
        --with-prechange-baseline) with_prechange_baseline=true ;;
        --regenerate-unsupported-format6)
            regenerate_unsupported=true
            with_prechange_baseline=true
            ;;
        --help|-h) usage; exit 0 ;;
        *) usage >&2; exit 2 ;;
    esac
    shift
done
mkdir -p "${work_root}"
work_root="$(cd -- "${work_root}" && pwd)"

release_commit=46a2d41ab16fead609884ee655e26e6baa1ce325
format_six_commit=db572a45a401d9e7284b321efba0adbd6d577e6c
runner_source="${repo_root}/core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/CanonicalIriCompatibilityProcess.java"
bulk_runner_source="${repo_root}/core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/bulk/CanonicalIriFormatSixBulkCompatibilityProcess.java"

# Every checkout and Maven repository is private to this verification, so building an old binary cannot replace a
# current SNAPSHOT dependency while the current implementation is being tested.
checkout() {
    local directory=$1 repository=$2 commit=$3
    if [[ ! -d "${directory}/.git" ]]; then
        git init -q "${directory}"
        git -C "${directory}" fetch --depth 1 "${repository}" "${commit}"
        git -C "${directory}" checkout --detach FETCH_HEAD
    fi
    [[ $(git -C "${directory}" rev-parse HEAD) == "${commit}" ]] || {
        echo "Unexpected producer commit in ${directory}" >&2
        exit 1
    }
    git -C "${directory}" diff --quiet
    git -C "${directory}" diff --cached --quiet
}

run_maven() {
    local directory=$1 log=$2
    shift 2
    if (cd "${directory}" && mvn -o "$@") >"${log}" 2>&1; then
        return
    fi
    if ! rg -q 'offline mode|offline has not been downloaded|Cannot access.*offline' "${log}"; then
        tail -80 "${log}" >&2
        return 1
    fi
    if ! (cd "${directory}" && mvn "$@") >"${log}" 2>&1; then
        tail -80 "${log}" >&2
        return 1
    fi
}

build_producer() {
    local version=$1 product_version=$2 repository=$3 commit=$4
    local directory="${work_root}/format-${version}"
    local checkout_directory="${directory}/source"
    mkdir -p "${directory}/runner"
    checkout "${checkout_directory}" "${repository}" "${commit}"
    echo "Building original format-${version} binary ${commit}"
    run_maven "${checkout_directory}" "${directory}/build.log" -B -ntp -Dmaven.repo.local=.m2_repo \
        -pl core/sail/lmdb -am -Pquick -DskipFrontend=true install
    run_maven "${checkout_directory}" "${directory}/classpath.log" -B -ntp -Dmaven.repo.local=.m2_repo \
        -pl core/sail/lmdb org.apache.maven.plugins:maven-dependency-plugin:3.8.1:build-classpath \
        -DincludeScope=test "-Dmdep.outputFile=${directory}/dependencies.txt"
    local classpath="${checkout_directory}/core/sail/lmdb/target/rdf4j-sail-lmdb-${product_version}.jar:$(cat "${directory}/dependencies.txt")"
    javac -proc:none -cp "${classpath}" -d "${directory}/runner" "${runner_source}"
    if [[ ${version} == 6 ]]; then
        javac -proc:none -cp "${classpath}" -d "${directory}/runner" "${bulk_runner_source}"
    fi
    printf '%s' "${directory}/runner:${classpath}" >"${directory}/classpath.txt"
}

build_producer 2 6.1.0 https://github.com/eclipse-rdf4j/rdf4j.git "${release_commit}"
if ${with_prechange_baseline}; then
    build_producer 6 6.2.0-SNAPSHOT https://github.com/HASMAC-AS/rdf4j.git "${format_six_commit}"
fi

if ${regenerate} || ${regenerate_unsupported}; then
    generation="${work_root}/fixtures-$(date -u +%Y%m%dT%H%M%SZ)"
    mkdir -p "${generation}"
    fixture_versions=()
    if ${regenerate}; then fixture_versions+=(2); fi
    if ${regenerate_unsupported}; then fixture_versions+=(6); fi
    for version in "${fixture_versions[@]}"; do
        commit=${release_commit}
        if [[ ${version} == 6 ]]; then
            commit=${format_six_commit}
        fi
        mkdir -p "${generation}/format-${version}"
        java -ea -cp "$(cat "${work_root}/format-${version}/classpath.txt")" \
            org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess create \
            "${generation}/format-${version}/store" "${generation}/format-${version}/manifest.properties" \
            "${commit}" >"${generation}/format-${version}/producer.log" 2>&1
        java -ea -cp "$(cat "${work_root}/format-${version}/classpath.txt")" \
            org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess verify \
            "${generation}/format-${version}/store" "${generation}/format-${version}/manifest.properties" \
            >"${generation}/format-${version}/original-reopen.log" 2>&1
    done
    python3 - "${generation}" "${repo_root}/core/sail/lmdb/src/test/resources/lmdb-compat" <<'PY'
import hashlib
import sys
from pathlib import Path
from zipfile import ZIP_DEFLATED, ZipFile, ZipInfo

generation, resources = map(Path, sys.argv[1:])
for fixture in sorted(generation.glob("format-*")):
    version = int(fixture.name.removeprefix("format-"))
    output = resources / ("canonical-iri-format-2.zip" if version == 2 else "unsupported-format-6.zip")
    with ZipFile(output, "w", compression=ZIP_DEFLATED, compresslevel=9) as archive:
        for path in sorted(fixture.rglob("*")):
            if not path.is_file() or path.name in ("lock", "lock.mdb", "producer.log", "original-reopen.log"):
                continue
            entry = ZipInfo(path.relative_to(fixture).as_posix(), date_time=(2026, 10, 29, 0, 0, 0))
            entry.compress_type = ZIP_DEFLATED
            entry.external_attr = 0o644 << 16
            archive.writestr(entry, path.read_bytes(), compresslevel=9)
    print(f"{output.name}: {hashlib.sha256(output.read_bytes()).hexdigest()}")
PY
fi

test_selection=LmdbCanonicalIriCompatibilityTest,LmdbCanonicalIriFormatPolicyTest
baseline_options=()
if ${with_prechange_baseline}; then
    test_selection+=,VersionedBulkWorkspaceFormatTest#originalFormatSixBinaryRejectsMarkerOnlyCanonicalGenerationWithoutChangingFiles
    baseline_options+=("-Drdf4j.lmdb.canonical.compat.classpath.format6=$(cat "${work_root}/format-6/classpath.txt")")
fi
echo "Building current module and verifying actual release compatibility and unsupported-format rejection"
run_maven "${repo_root}" "${work_root}/current-build.log" -B -ntp -Dmaven.repo.local=.m2_repo \
    -pl core/sail/lmdb -am -Pquick -DskipFrontend=true install
run_maven "${repo_root}" "${work_root}/current-tests.log" -B -ntp -Dmaven.repo.local=.m2_repo \
    -pl core/sail/lmdb "-Dtest=${test_selection}" -DskipITs \
    -DforkCount=1 -Drdf4j.lmdb.test.maxHeap=2G \
    -Dformatter.skip=true -Dimpsort.skip=true -Djapicmp.skip=true -Denforcer.skip=true \
    "-Drdf4j.lmdb.canonical.compat.classpath.format2=$(cat "${work_root}/format-2/classpath.txt")" \
    "${baseline_options[@]}" verify
python3 "${repo_root}/scripts/agent-evidence.py" --log "${work_root}/current-tests.log" \
    "${repo_root}/core/sail/lmdb/target/surefire-reports"
